// Build trades_observed rows. This table is the ONLY source of market
// volume in AD4 - v_band_volume, v_city_volume, the thin-market warnings,
// the liquidity factor in the opportunity ranking, the calculator's volume
// warning and the Goals feasibility read all derive from it. If this
// workflow stops, every volume figure in the platform silently reads $0
// and every band is flagged thin.
//
// GROUNDED: the target columns, from sql/ad4_00_preflight.sql -
// trades_observed(city_key, band_id, token_id, side, price, size, observed_at).
//
// band_id is what makes BAND-level volume possible. Without it only
// city-level volume works and every band still reads thin, so map it if
// the upstream payload carries a token id we can resolve.
//
// NOT GROUNDED: the upstream payload shape. Map the reads below.
const bands = $('Load bands').all().map(i => i.json);

// token id -> {band_id, city_key}, so a trade on either leg attributes home.
const byToken = new Map();
for (const b of bands) {
  if (b.token_yes) byToken.set(String(b.token_yes), b);
  if (b.token_no)  byToken.set(String(b.token_no),  b);
}

const raw = $('Fetch trades').all().map(i => i.json).flat();
const rows = [];
let unmatched = 0;

for (const t of raw) {
  const token = String(t.asset_id ?? t.token_id ?? t.tokenId ?? '');
  const band = byToken.get(token);
  if (!band) { unmatched++; continue; }

  const price = Number(t.price);
  const size = Number(t.size ?? t.amount ?? t.shares);
  if (!Number.isFinite(price) || !Number.isFinite(size) || size <= 0) continue;

  // Trade timestamps are often unix seconds. Normalise to ISO, and keep
  // this as the OBSERVED time - never substitute the ingest run's clock.
  let ts = t.timestamp ?? t.match_time ?? t.observed_at;
  if (typeof ts === 'number' || /^\d+$/.test(String(ts))) {
    const n = Number(ts);
    ts = new Date(n < 1e12 ? n * 1000 : n).toISOString();
  } else {
    ts = new Date(ts).toISOString();
  }

  rows.push({
    city_key: band.city_key || null,
    band_id: band.band_id,
    token_id: token,
    side: (t.side || t.taker_side || '').toUpperCase() || null,
    price,
    size,
    observed_at: ts,
  });
}

const volume = rows.reduce((s, r) => s + r.price * r.size, 0);
return [{ json: { rows, n: rows.length, unmatched, volume_usd: Number(volume.toFixed(2)) } }];

const p = $('Map trades to bands').first().json;
const d = $('Refresh volume rollups').first().json || {};
return [{ json: { summary:
  `AD4 P0.4: ${p.n} trades ($${p.volume_usd}) written, ${p.unmatched} unmatched tokens. ` +
  `Rollups: ${d.city_day_volume_rows ?? '?'} city-day, ${d.band_day_volume_rows ?? '?'} band-day rows.` } }];
